"""
Threat Detection Engine Module
Implements rule-based security threat detection algorithms for the Mini SIEM system.
Stage 2: Security Threat Detection Engine.
"""
from dataclasses import dataclass, asdict
from datetime import timedelta
from typing import List, Dict, Any, Optional
import pandas as pd


@dataclass
class SecurityAlert:
    """Represents a standardized security alert generated by the detection engine."""
    alert_id: str
    timestamp: str
    source_ip: str
    username: str
    threat_type: str
    severity: str  # Critical, High, Medium, Low
    detection_rule: str
    explanation: str

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class DetectionEngine:
    """
    Rule-Based Security Detection Engine.
    Evaluates normalized event logs against security rules to identify potential attacks.
    """

    def __init__(
        self,
        brute_force_threshold: int = 3,
        brute_force_window_minutes: int = 15,
        failed_logins_threshold: int = 2,
        failed_logins_window_minutes: int = 30,
        suspicious_ip_threshold: int = 2,
        suspicious_ip_window_minutes: int = 60,
        suspicious_ip_min_categories: int = 2,
        port_scan_threshold: int = 2,
        port_scan_window_minutes: int = 15,
    ):
        self.brute_force_threshold = brute_force_threshold
        self.brute_force_window_minutes = brute_force_window_minutes
        self.failed_logins_threshold = failed_logins_threshold
        self.failed_logins_window_minutes = failed_logins_window_minutes
        self.suspicious_ip_threshold = suspicious_ip_threshold
        self.suspicious_ip_window_minutes = suspicious_ip_window_minutes
        self.suspicious_ip_min_categories = suspicious_ip_min_categories
        self.port_scan_threshold = port_scan_threshold
        self.port_scan_window_minutes = port_scan_window_minutes
        self._alert_counter = 0

    def _next_alert_id(self, prefix: str = "ALT") -> str:
        self._alert_counter += 1
        return f"{prefix}-{self._alert_counter:03d}"

    def reset_counter(self) -> None:
        """Resets the alert ID sequence counter."""
        self._alert_counter = 0

    # ------------------------------------------------------------------
    # Rule 1: Brute Force Detection
    # ------------------------------------------------------------------
    def detect_brute_force(self, df: pd.DataFrame) -> List[SecurityAlert]:
        """
        Rule 1: Detect repeated failed login attempts from the same source IP
        within a defined sliding time window.
        Criteria:
        - event_type == 'login' (case-insensitive)
        - status == 'failed' (case-insensitive)
        - Grouped by source_ip
        - Count within window >= brute_force_threshold
        """
        alerts: List[SecurityAlert] = []
        if df.empty:
            return alerts

        is_login = df["event_type"].astype(str).str.lower() == "login"
        is_failed = df["status"].astype(str).str.lower() == "failed"
        failed_logins = df[is_login & is_failed].copy()

        if failed_logins.empty:
            return alerts

        if not pd.api.types.is_datetime64_any_dtype(failed_logins["timestamp"]):
            failed_logins["timestamp"] = pd.to_datetime(failed_logins["timestamp"], errors="coerce")

        window = timedelta(minutes=self.brute_force_window_minutes)

        for ip, group in failed_logins.groupby("source_ip"):
            sorted_group = group.sort_values(by="timestamp").reset_index(drop=True)
            n = len(sorted_group)

            for i in range(n):
                start_time = sorted_group.loc[i, "timestamp"]
                in_window = sorted_group[
                    (sorted_group["timestamp"] >= start_time) &
                    (sorted_group["timestamp"] <= start_time + window)
                ]

                if len(in_window) >= self.brute_force_threshold:
                    latest_evt = in_window.iloc[-1]
                    usernames = in_window["username"].unique().tolist()
                    user_str = ", ".join(usernames) if len(usernames) <= 2 else f"{usernames[0]} (+{len(usernames)-1} others)"

                    severity = "Critical" if len(in_window) >= 5 else "High"
                    alert = SecurityAlert(
                        alert_id=self._next_alert_id("ALT-BF"),
                        timestamp=str(latest_evt["timestamp"]),
                        source_ip=str(ip),
                        username=user_str,
                        threat_type="Brute Force Attack",
                        severity=severity,
                        detection_rule="RULE-01: Brute Force (Source IP)",
                        explanation=(
                            f"Detected {len(in_window)} failed login attempts from source IP {ip} "
                            f"within {self.brute_force_window_minutes} minutes "
                            f"(Threshold: {self.brute_force_threshold}). Targeted accounts: {user_str}."
                        )
                    )
                    alerts.append(alert)
                    break

        return alerts

    # ------------------------------------------------------------------
    # Rule 2: Repeated Failed Logins by Username
    # ------------------------------------------------------------------
    def detect_repeated_failed_logins(self, df: pd.DataFrame) -> List[SecurityAlert]:
        """
        Rule 2: Detect multiple failed login attempts targeting the same username.
        Criteria:
        - event_type == 'login'
        - status == 'failed'
        - Ignores missing, empty, null, or 'unknown' usernames to prevent false positives
        - Grouped by valid username
        - Count within window >= failed_logins_threshold
        """
        alerts: List[SecurityAlert] = []
        if df.empty:
            return alerts

        is_login = df["event_type"].astype(str).str.lower() == "login"
        is_failed = df["status"].astype(str).str.lower() == "failed"
        failed_logins = df[is_login & is_failed].copy()

        if failed_logins.empty:
            return alerts

        # Helper to validate real account names (filter out missing/empty/null/unknown)
        def is_valid_username(val: Any) -> bool:
            if pd.isna(val):
                return False
            cleaned = str(val).strip().lower()
            if not cleaned or cleaned in ["unknown", "none", "null", "nan", "undefined", "-", "n/a"]:
                return False
            return True

        valid_user_mask = failed_logins["username"].apply(is_valid_username)
        failed_logins = failed_logins[valid_user_mask].copy()

        if failed_logins.empty:
            return alerts

        if not pd.api.types.is_datetime64_any_dtype(failed_logins["timestamp"]):
            failed_logins["timestamp"] = pd.to_datetime(failed_logins["timestamp"], errors="coerce")

        window = timedelta(minutes=self.failed_logins_window_minutes)

        for username, group in failed_logins.groupby("username"):
            sorted_group = group.sort_values(by="timestamp").reset_index(drop=True)
            n = len(sorted_group)

            for i in range(n):
                start_time = sorted_group.loc[i, "timestamp"]
                in_window = sorted_group[
                    (sorted_group["timestamp"] >= start_time) &
                    (sorted_group["timestamp"] <= start_time + window)
                ]

                if len(in_window) >= self.failed_logins_threshold:
                    latest_evt = in_window.iloc[-1]
                    ips = in_window["source_ip"].unique().tolist()
                    ip_str = ", ".join(ips)

                    # High priority for administrative / privileged accounts
                    is_privileged = str(username).lower() in ["admin", "root", "administrator", "system"]
                    severity = "High" if is_privileged else "Medium"

                    alert = SecurityAlert(
                        alert_id=self._next_alert_id("ALT-FL"),
                        timestamp=str(latest_evt["timestamp"]),
                        source_ip=ip_str,
                        username=str(username),
                        threat_type="Repeated Failed Logins",
                        severity=severity,
                        detection_rule="RULE-02: Targeted User Authentication Failures",
                        explanation=(
                            f"Account '{username}' targeted by {len(in_window)} failed login attempts "
                            f"within {self.failed_logins_window_minutes} minutes "
                            f"(Threshold: {self.failed_logins_threshold}). Source IPs: {ip_str}."
                        )
                    )
                    alerts.append(alert)
                    break

        return alerts

    # ------------------------------------------------------------------
    # Rule 3: Suspicious IP Activity (Multi-Category Correlation)
    # ------------------------------------------------------------------
    def detect_suspicious_ip_activity(self, df: pd.DataFrame) -> List[SecurityAlert]:
        """
        Rule 3: Identify IP addresses associated with multiple distinct suspicious event categories
        within a configurable sliding time window.
        Criteria:
        - status in ['alert', 'blocked', 'warning', 'failed'] OR
        - event_type in ['security alert', 'malware detected', 'port scan', 'firewall block', 'privilege escalation']
        - Grouped by source_ip
        - Number of suspicious events within window >= suspicious_ip_threshold
        - Number of DISTINCT event_type categories within window >= suspicious_ip_min_categories (default 2)
        """
        alerts: List[SecurityAlert] = []
        if df.empty:
            return alerts

        suspicious_status = df["status"].astype(str).str.lower().isin(["alert", "blocked", "warning", "failed"])
        suspicious_types = df["event_type"].astype(str).str.lower().isin([
            "security alert", "malware detected", "port scan", "firewall block", "privilege escalation"
        ])

        suspicious_df = df[suspicious_status | suspicious_types].copy()
        if suspicious_df.empty:
            return alerts

        if not pd.api.types.is_datetime64_any_dtype(suspicious_df["timestamp"]):
            suspicious_df["timestamp"] = pd.to_datetime(suspicious_df["timestamp"], errors="coerce")

        window = timedelta(minutes=self.suspicious_ip_window_minutes)

        for ip, group in suspicious_df.groupby("source_ip"):
            sorted_group = group.sort_values(by="timestamp").reset_index(drop=True)
            n = len(sorted_group)

            for i in range(n):
                start_time = sorted_group.loc[i, "timestamp"]
                in_window = sorted_group[
                    (sorted_group["timestamp"] >= start_time) &
                    (sorted_group["timestamp"] <= start_time + window)
                ]

                distinct_categories = in_window["event_type"].dropna().unique().tolist()

                if (
                    len(in_window) >= self.suspicious_ip_threshold
                    and len(distinct_categories) >= self.suspicious_ip_min_categories
                ):
                    latest_evt = in_window.iloc[-1]
                    types_summary = ", ".join(distinct_categories)
                    statuses = in_window["status"].dropna().unique().tolist()

                    has_malware = any("malware" in str(t).lower() for t in distinct_categories)
                    has_escalation = any("escalation" in str(t).lower() for t in distinct_categories)
                    severity = "Critical" if (has_malware or has_escalation or len(in_window) >= 4) else "High"

                    alert = SecurityAlert(
                        alert_id=self._next_alert_id("ALT-SIP"),
                        timestamp=str(latest_evt["timestamp"]),
                        source_ip=str(ip),
                        username=str(latest_evt.get("username", "Unknown")),
                        threat_type="Suspicious IP Activity",
                        severity=severity,
                        detection_rule="RULE-03: Multi-Category Suspicious IP Correlation",
                        explanation=(
                            f"IP address {ip} generated {len(in_window)} suspicious events across "
                            f"{len(distinct_categories)} distinct categories: [{types_summary}] "
                            f"with statuses [{', '.join(statuses)}] within {self.suspicious_ip_window_minutes} minutes "
                            f"(Threshold: {self.suspicious_ip_threshold} events, {self.suspicious_ip_min_categories} categories)."
                        )
                    )
                    alerts.append(alert)
                    break

        return alerts

    # ------------------------------------------------------------------
    # Rule 4: Port Scan Detection (Requires Repeated Events in Window)
    # ------------------------------------------------------------------
    def detect_port_scans(self, df: pd.DataFrame) -> List[SecurityAlert]:
        """
        Rule 4: Detect repeated port scan events from the same source IP within a configurable time window.
        Criteria:
        - event_type == 'port scan' OR details contains reconnaissance keywords
        - Grouped by source_ip
        - Number of scan events within port_scan_window_minutes >= port_scan_threshold (default 2 in 15 mins)
        """
        alerts: List[SecurityAlert] = []
        if df.empty:
            return alerts

        is_port_scan_type = df["event_type"].astype(str).str.lower() == "port scan"
        details_match = df["details"].astype(str).str.lower().str.contains(
            "port scan|syn scan|connection probes|port probe", na=False
        )

        scan_df = df[is_port_scan_type | details_match].copy()
        if scan_df.empty:
            return alerts

        if not pd.api.types.is_datetime64_any_dtype(scan_df["timestamp"]):
            scan_df["timestamp"] = pd.to_datetime(scan_df["timestamp"], errors="coerce")

        window = timedelta(minutes=self.port_scan_window_minutes)

        for ip, group in scan_df.groupby("source_ip"):
            sorted_group = group.sort_values(by="timestamp").reset_index(drop=True)
            n = len(sorted_group)

            for i in range(n):
                start_time = sorted_group.loc[i, "timestamp"]
                in_window = sorted_group[
                    (sorted_group["timestamp"] >= start_time) &
                    (sorted_group["timestamp"] <= start_time + window)
                ]

                if len(in_window) >= self.port_scan_threshold:
                    latest_evt = in_window.iloc[-1]
                    scan_details = latest_evt.get("details", "Port reconnaissance activity")
                    severity = "High" if len(in_window) >= 3 else "Medium"

                    alert = SecurityAlert(
                        alert_id=self._next_alert_id("ALT-PS"),
                        timestamp=str(latest_evt["timestamp"]),
                        source_ip=str(ip),
                        username=str(latest_evt.get("username", "System")),
                        threat_type="Port Scanning",
                        severity=severity,
                        detection_rule="RULE-04: Network Port Scan Reconnaissance",
                        explanation=(
                            f"Detected {len(in_window)} port scanning events from source IP {ip} "
                            f"within {self.port_scan_window_minutes} minutes "
                            f"(Threshold: {self.port_scan_threshold}). Latest signature: \"{scan_details}\"."
                        )
                    )
                    alerts.append(alert)
                    break

        return alerts

    # ------------------------------------------------------------------
    # Rule 5: Privilege Escalation
    # ------------------------------------------------------------------
    def detect_privilege_escalation(self, df: pd.DataFrame) -> List[SecurityAlert]:
        """
        Rule 5: Flag suspicious privilege escalation events based on defined criteria.
        Criteria:
        - event_type == 'privilege escalation'
        - AND status in ['alert', 'failed', 'blocked', 'warning'] OR
        - details indicates unauthorized/unapproved invocation (e.g. without valid ticket)
        """
        alerts: List[SecurityAlert] = []
        if df.empty:
            return alerts

        is_priv_esc = df["event_type"].astype(str).str.lower() == "privilege escalation"
        if not is_priv_esc.any():
            return alerts

        priv_df = df[is_priv_esc].copy()

        for _, row in priv_df.iterrows():
            status_lower = str(row.get("status", "")).lower()
            details_lower = str(row.get("details", "")).lower()

            is_suspicious_status = status_lower in ["alert", "failed", "blocked", "warning"]
            is_suspicious_detail = any(kw in details_lower for kw in [
                "without valid", "unauthorized", "unapproved", "denied", "violation", "ticket"
            ])

            if is_suspicious_status or is_suspicious_detail:
                alert = SecurityAlert(
                    alert_id=self._next_alert_id("ALT-PE"),
                    timestamp=str(row["timestamp"]),
                    source_ip=str(row.get("source_ip", "Unknown")),
                    username=str(row.get("username", "Unknown")),
                    threat_type="Privilege Escalation",
                    severity="Critical",
                    detection_rule="RULE-05: Unauthorized Privilege Escalation",
                    explanation=(
                        f"Suspicious privilege escalation by user '{row.get('username')}' "
                        f"from IP {row.get('source_ip')}. Detail: \"{row.get('details')}\"."
                    )
                )
                alerts.append(alert)

        return alerts

    # ------------------------------------------------------------------
    # Master Execution: Run All Rules
    # ------------------------------------------------------------------
    def run_all_rules(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Executes all 5 detection rules against the provided log DataFrame.
        Returns a structured DataFrame of all generated SecurityAlerts.
        """
        self.reset_counter()
        all_alerts: List[SecurityAlert] = []

        all_alerts.extend(self.detect_brute_force(df))
        all_alerts.extend(self.detect_repeated_failed_logins(df))
        all_alerts.extend(self.detect_suspicious_ip_activity(df))
        all_alerts.extend(self.detect_port_scans(df))
        all_alerts.extend(self.detect_privilege_escalation(df))

        if not all_alerts:
            return pd.DataFrame(columns=[
                "alert_id", "timestamp", "source_ip", "username",
                "threat_type", "severity", "detection_rule", "explanation"
            ])

        records = [a.to_dict() for a in all_alerts]
        alerts_df = pd.DataFrame(records)

        if "timestamp" in alerts_df.columns:
            alerts_df["parsed_ts"] = pd.to_datetime(alerts_df["timestamp"], errors="coerce")
            alerts_df = alerts_df.sort_values(by="parsed_ts", ascending=False).drop(columns=["parsed_ts"]).reset_index(drop=True)

        return alerts_df
